        if all(grid[r][c] == b for c in range(w) if grid[r][c] != 7):
            p = r + 1
    n = max(n, p)
    cnt = [0] * (n + 1)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 7:
                cnt[(r - c) % (n + 1)] += 1
    # Dense seed: a diagonal stripe pattern; sparse seed: a toroidal stamp.
    if sum(grid[r][c] != 7 for r in range(n) for c in range(n)) > 3 * n:
        out = [[7] * w for _ in range(h)]
        for r in range(h):
