                if k == 0:
                    out[r][c] = a
                elif k == n - 1:
                    out[r][c] = b
        return out
    cnt[-1] = 0
    start = max(range(len(cnt)), key=lambda k: cnt[k])
    out = [[7] * w for _ in range(h)]
